20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
27	    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
28	    @Mapping(target = "membershipNumber", source = "owner", qualifiedByName = "formatMembershipNumber")
29	    @Mapping(target = "membershipLevel", source = "owner", qualifiedByName = "formatMembershipLevel")
30	    @Mapping(target = "locality", source = "owner", qualifiedByName = "formatLocality")
31	    @Mapping(target = "contactPreference", source = "owner", qualifiedByName = "formatContactPreference")
32	    @Mapping(target = "bulkSignupWarning", ignore = true)
33	    OwnerDto toOwnerDto(Owner owner);
34	
35	    /**
36	     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
37	     * last names, as required by the API's read-only {@code displayName} field.
38	     *
39	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
40	     * applied only where referenced via {@code qualifiedByName}.
41	     */
42	    @Named("formatDisplayName")
43	    default String formatDisplayName(Owner owner) {
44	        if (owner == null) {
45	            return null;
46	        }
47	        return owner.getLastName() + ", " + owner.getFirstName();
48	    }
49	
50	    /**
51	     * Formats an owner's initials as the upper-cased first letters of the first and last
52	     * names, dot-separated with a trailing dot (e.g. {@code 'J.S.'}), as required by the
53	     * API's read-only {@code initials} field.
54	     *
55	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
56	     * applied only where referenced via {@code qualifiedByName}.
57	     */
58	    @Named("formatInitials")
59	    default String formatInitials(Owner owner) {
60	        if (owner == null) {
61	            return null;
62	        }
63	        return initial(owner.getFirstName()) + initial(owner.getLastName());
64	    }
65	
66	    /**
67	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
68	     * {@code customerCode} is the owner's customer code and {@code YY} is the last two
69	     * digits of the registration date's year (e.g. {@code 'SMI-0007-M26'}), as required
70	     * by the API's read-only {@code membershipNumber} field. Returns {@code null} when
71	     * either the customer code or registration date is absent.
72	     *
73	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
74	     * applied only where referenced via {@code qualifiedByName}.
75	     */
76	    @Named("formatMembershipNumber")
77	    default String formatMembershipNumber(Owner owner) {
78	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
79	            return null;
80	        }
81	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
82	    }
