17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.slf4j.Logger;
23	import org.slf4j.LoggerFactory;
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
101	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
102	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        if (this.clinicService.isDailyRegistrationAtCapacity()) {
111	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
112	        }
113	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
114	        if (sharesHousehold) {
115	            owner.setHouseholdId(this.clinicService.householdIdFor(owner.getLastName(), owner.getAddress()));
116	        }
117	        // All duplicate detection is consolidated into the single derived identity key: reject only
118	        // when the new owner's whole identity key (telephone|email|householdId) matches an existing one.
119	        if (this.clinicService.isIdentityKeyInUse(owner)) {
120	            return new ResponseEntity<>(HttpStatus.CONFLICT);
121	        }
122	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
123	            return new ResponseEntity<>(HttpStatus.CONFLICT);
124	        }
125	        this.clinicService.saveOwner(owner);
126	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
127	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
128	            ownerMapper.formatMembershipLevel(owner));
129	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
130	        ownerDto.setBulkSignupWarning(this.clinicService.isBulkSignupDay());
131	        headers.setLocation(UriComponentsBuilder.newInstance()
132	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
133	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
139	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
140	        if (currentOwner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        currentOwner.setAddress(ownerFieldsDto.getAddress());
144	        currentOwner.setCity(ownerFieldsDto.getCity());
145	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
146	        currentOwner.setLastName(ownerFieldsDto.getLastName());
147	        currentOwner.setTelephone(ownerMapper.normalizeTelephone(ownerFieldsDto.getTelephone()));
148	        currentOwner.setEmail(ownerMapper.normalizeEmail(ownerFieldsDto.getEmail()));
149	        this.clinicService.saveOwner(currentOwner);
150	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
151	    }
152	
153	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
154	    @Transactional
155	    @Override
156	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
157	        Owner owner = this.clinicService.findOwnerById(ownerId);
158	        if (owner == null) {
159	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
160	        }
161	        this.clinicService.deleteOwner(owner);
162	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        HttpHeaders headers = new HttpHeaders();
173	        Pet pet = petMapper.toPet(petFieldsDto);
174	        owner.setId(ownerId);
175	        pet.setOwner(owner);
176	        pet.getType().setName(null);
177	        this.clinicService.savePet(pet);
178	        PetDto petDto = petMapper.toPetDto(pet);
179	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
180	            .buildAndExpand(pet.getId()).toUri());
181	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
187	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
188	        if (currentOwner != null) {
189	            Pet currentPet = this.clinicService.findPetById(petId);
190	            if (currentPet != null) {
191	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
192	                currentPet.setName(petFieldsDto.getName());
193	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
194	                this.clinicService.savePet(currentPet);
195	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
196	            }
197	        }
198	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	    }
200	
201	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
202	    @Override
203	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
204	        HttpHeaders headers = new HttpHeaders();
205	        Visit visit = visitMapper.toVisit(visitFieldsDto);
206	        Pet pet = new Pet();
207	        pet.setId(petId);
208	        visit.setPet(pet);
209	        this.clinicService.saveVisit(visit);
