156	        BindingErrorsResponse errors = new BindingErrorsResponse();
157	        BindingResult bindingResult = e.getBindingResult();
158	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
159	        if (bindingResult.hasErrors()) {
160	            errors.addAllErrors(bindingResult);
161	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
162	                .map(FieldError::getField)
163	                .distinct()
